    end
    on_intel do
      url "https://github.com/goadesign/chorus/releases/download/v0.12.1/chorus_0.12.1_darwin_amd64.tar.gz"
      sha256 "1e123edcf8093e73e2fc3c4b8d4aa29fd9b031ee320e1455fa72df19c02c091e"
